SELECT id,tenant_id AS tenantId,customer_id AS customerId,mode,reason,updated_by AS updatedBy,
  updated_at AS updatedAt,version FROM crm_ai_chat_delegation_customer
WHERE tenant_id=#{tenantId} AND customer_id=#{customerId}

mapper.update:
UPDATE crm_ai_chat_delegation_run SET status='SKIPPED',reason_masked=#{reason},next_attempt_at=NULL,
  lease_owner=NULL,lease_expires_at=NULL,version=version+1,updated_at=#{now}
WHERE tenant_id=#{tenantId} AND customer_id=#{customerId}
  AND status IN ('QUEUED','DEFERRED','RETRY_GENERATE','READY_TO_SEND','RETRY_SEND')

mapper.select:
SELECT  FROM crm_ai_chat_delegation_run r WHERE r.tenant_id=#{tenantId}
  AND (((r.status IN ('QUEUED','DEFERRED','RETRY_GENERATE')) AND (r.next_attempt_at IS NULL OR r.next_attempt_at<=#{now}))
    OR (r.status='GENERATING' AND r.lease_expires_at<#{now}))
ORDER BY r.id LIMIT #{limit}

SELECT  FROM crm_ai_chat_delegation_run r WHERE r.tenant_id=#{tenantId}
  AND r.status IN ('READY_TO_SEND','RETRY_SEND') AND (r.next_attempt_at IS NULL OR r.next_attempt_at<=#{now})
ORDER BY r.id LIMIT #{limit}

mapper.update:
UPDATE crm_ai_chat_delegation_run SET status='GENERATING',generation_attempts=generation_attempts+1,
  lease_owner=#{owner},lease_expires_at=#{leaseExpiresAt},next_attempt_at=NULL,version=version+1,updated_at=#{now}
WHERE tenant_id=#{tenantId} AND id=#{id} AND version=#{expectedVersion}
  AND ((status IN ('QUEUED','DEFERRED','RETRY_GENERATE') AND (next_attempt_at IS NULL OR next_attempt_at<=#{now}))
    OR (status='GENERATING' AND lease_expires_at<#{now}))

UPDATE crm_ai_chat_delegation_run SET status='SENDING',send_attempts=send_attempts+1,
  lease_owner=#{owner},lease_expires_at=#{leaseExpiresAt},next_attempt_at=NULL,version=version+1,updated_at=#{now}
WHERE tenant_id=#{tenantId} AND id=#{id} AND version=#{expectedVersion}
  AND status IN ('READY_TO_SEND','RETRY_SEND') AND (next_attempt_at IS NULL OR next_attempt_at<=#{now})

UPDATE crm_ai_chat_delegation_run SET status='READY_TO_SEND',reason_masked=NULL,reply_cipher=#{replyCipher},
  intent=#{intent},risk_flags_json=#{riskFlagsJson},ai_provider=#{aiProvider},ai_model=#{aiModel},
  next_attempt_at=#{now},lease_owner=NULL,lease_expires_at=NULL,version=version+1,updated_at=#{now}
WHERE tenant_id=#{tenantId} AND id=#{id} AND version=#{expectedVersion} AND status='GENERATING' AND lease_owner=#{owner}

UPDATE crm_ai_chat_delegation_run SET status=#{targetStatus},reason_masked=#{reasonMasked},
  next_attempt_at=#{nextAttemptAt},lease_owner=NULL,lease_expires_at=NULL,version=version+1,updated_at=#{now}
WHERE tenant_id=#{tenantId} AND id=#{id} AND version=#{expectedVersion} AND status=#{expectedStatus}

UPDATE crm_ai_chat_delegation_run SET status=#{status},reason_masked=#{reasonMasked},send_provider=#{provider},
  provider_message_id=#{providerMessageId},next_attempt_at=#{nextAttemptAt},lease_owner=NULL,lease_expires_at=NULL,
  version=version+1,updated_at=#{now}
WHERE tenant_id=#{tenantId} AND id=#{id} AND version=#{expectedVersion} AND status='SENDING' AND lease_owner=#{owner}

mapper.select:
SELECT COUNT(*) FROM crm_ai_chat_delegation_run
WHERE tenant_id=#{tenantId} AND customer_id=#{customerId} AND send_attempted_at IS NOT NULL
  AND send_attempted_at>=#{since}

SELECT  FROM crm_ai_chat_delegation_run r WHERE r.tenant_id=#{tenantId}
AND r.customer_id=#{customerId}
AND r.status=#{status}
AND  ORDER BY r.id DESC LIMIT #{size} OFFSET #{offset}

